import {STATIONS} from './rail.js?v=scenario-result-1';
import {changeTransit} from './transport.js?v=scenario-result-1';
import {recompute} from './engine.js?v=scenario-result-1';
export function showTransport(ui){const {city,dialog,close,update,save,clearUndo,notify,review,setTool,setLayer}=ui,c=city(),s=c.stats,$=v=>document.querySelector(v),fmt=v=>'§'+Math.round(v).toLocaleString();
 dialog('Transport & commuting',`<h3>Mountain tunnels</h3><p>${c.stats.tunnels} tunnels · ${c.stats.roadTunnelTiles} road, ${c.stats.railTunnelTiles} rail and ${c.stats.highwayTunnelTiles} highway underground tiles. Drag a straight route between equal-height dry portals across a ridge with at least six buried tiles. Engineers quote the cost before construction. Remove either portal to disconnect the tunnel; interior terrain is protected.</p><button id="showTunnels">View tunnels</button><p>${s.transitStrike?'Transit workers are on strike. Restore funding to 100% and run one month.':s.congestedRoads?'Traffic is backing up. Put bus stops near homes or build another road route.':'Connect homes to workplaces. Bus stops let residents board near home and get off near work without a destination stop.'}</p><div class="metric-grid"><div><small>Workers / reachable jobs filled</small><strong>${s.commuters} / ${s.commuters-s.unemployed}</strong></div><div><small>Rail / subway passengers</small><strong>${s.trainRiders.toFixed(1)}</strong></div><div><small>Operating rail stations</small><strong>${s.activeStations} / ${s.stations}</strong></div><div><small>Bus passengers</small><strong>${s.busRiders.toFixed(1)}</strong></div><div><small>Average road journey</small><strong>${s.averageCommute.toFixed(1)} tiles</strong></div><div><small>Congested road tiles</small><strong>${s.congestedRoads}</strong></div><div><small>Operating stops</small><strong>${s.activeBusStops} / ${s.busStops}</strong></div><div><small>Highway / active ramps</small><strong>${s.highwayTiles} / ${s.activeRamps}</strong></div><div><small>Highway congestion</small><strong>${s.congestedHighways} tiles</strong></div><div><small>Road bridge tiles</small><strong>${s.bridgeTiles}</strong></div></div><div class="actions"><button id="trafficMap">Traffic map</button><button id="transitMap">Bus stops & usage</button><button id="buildBus" class="primary">Place bus stop · §150</button><button id="buildRoad">Build road / bridge</button></div><h3>Airports & seaports</h3><p>Operating airports: ${s.activeAirports}. Operating seaports: ${s.activeSeaports}. These facilities increase commercial and industrial demand.</p><div class="actions"><button data-transit-tool="airport">Zone airport</button><button data-transit-tool="seaport">Zone seaport</button></div><p>Airports need at least 3 × 5 tiles; seaports need 2 × 6 and shoreline water reaching the map edge. Supply power and water to every tile and a nearby road. Development takes six supplied months. Inspect vacant zones for missing requirements.</p>${s.facilityPlots.map(p=>`<p><strong>${p.type==='airport'?'Airport':'Seaport'} · ${p.x+1}, ${p.y+1}</strong>: ${p.reason}</p>`).join('')}<h3>Highways & ramps</h3><p>Highways are elevated and carry four times the traffic of roads. They can cross roads without connecting. Place an on-ramp on an empty tile diagonally beside a crossing to connect the two levels; provide ramps at both ends of a highway journey. Residents enter through ordinary roads, not straight from zones.</p><div class="actions"><button data-transit-tool="highway">Lay highway · §60/tile</button><button data-transit-tool="ramp">On-ramp · §150</button><button data-transit-tool="removeHighway">Remove highway</button></div><p>Highway bridges cost §250/water tile. Removing highway preserves surface roads and tracks. Road funding maintains highways and ramps. Routes weigh highway speed and existing congestion.</p><h3>Rail & subway</h3><p>Rail stations must touch track. Subway stations work over or beside underground rail. Place stations near both homes and workplaces; connect their tracks. A rail–subway connection joins the two networks only where it touches both.</p><div class="actions"><button id="railMap">Rail usage</button><button id="subwayMap">Subway · underground</button><button data-transit-tool="rail">Lay rail</button><button data-transit-tool="subway">Lay subway</button>${Object.entries(STATIONS).map(([k,v])=>`<button data-transit-tool="${k}">${v.name} · ${fmt(v.cost)}</button>`).join('')}</div><p>${s.railTiles} rail tiles · ${s.subwayTiles} subway tiles. Inspect stations and tracks for passenger counts. Track removal tools preserve the other underground networks.</p><h3>Transit budget</h3><label>Funding · <strong id="transitFundingValue">${c.transport.funding}%</strong><input id="transitFunding" type="range" min="0" max="150" step="5" value="${c.transport.funding}"></label><p>Transit condition: ${Math.round(c.transport.condition)}%. Underfunding reduces ridership as equipment deteriorates. Six months below 50% can trigger a strike. Full funding repairs equipment and ends a strike after one month.</p><p id="transitPreview" aria-live="polite"></p><button id="applyTransit">Apply transit funding</button><h3>Plan useful bus stops</h3><p>Place a stop on dry land directly beside a road, within three tiles of homes. It must connect to the road network residents use to reach a job. Buses travel on roads; destination stops are not required. Inspect a stop to see its passenger count. Stops cost §5/month at full funding; fares appear in Budget.</p><h3>Cross the water</h3><p>Choose Road and drag in a straight line from one dry bank across water to another. Water tiles cost §100 each. City engineers quote the full price before you approve construction. Bridges carry roads, garbage trucks, and civic road access. Sideways intersections on water are not allowed.</p><h3>Outside market access</h3><p>${s.marketConnectedPlots.commercial} / ${s.marketZonedPlots.commercial} commercial plots and ${s.marketConnectedPlots.industrial} / ${s.marketZonedPlots.industrial} industrial plots can reach a paid border route or operating airport/seaport. Rail connections need a working station. Isolated border stubs provide no benefit to disconnected businesses; multiple routes to the same land neighbor count once per plot. Inspect a business to see its connections and local demand support.</p><h3>Airport activity</h3><p>Operating airports bring periodic aircraft over the city. Their direction follows the facility’s long axis. Pause holds flights in place; reduced-motion settings hide them. These flights show airport activity and do not model individual passengers or landing schedules.</p><h3>Harbor activity</h3><p>Cargo ships load at operating seaports and follow open water to the map edge. Pause holds their position. Bridges and blocked channels prevent this visual route; shipping activity adds no separate income.</p><h3>Transport checkpoint</h3><ol><li>${s.activeAirports||s.activeSeaports?'✓ ':''}Develop an airport or a waterfront seaport.</li><li>${s.bridgeTiles?'✓ ':''}Build a road bridge between dry banks.</li><li>${s.busRiders>0?'✓ ':''}Get residents using a nearby bus stop.</li><li>${s.trainRiders>0?'✓ ':''}Carry passengers on a rail or subway route.</li><li>${s.congestedRoads===0?'✓ ':''}Keep roads below congestion capacity.</li><li>${c.transport.condition>=90?'✓ ':''}Keep transit in good condition.</li></ol><p class="fine">This is the first transport slice. Road routing, traffic and bus usage are approximate. Multi-level tunnel junctions and detailed traffic calibration remain unfinished.</p><button id="reviewTransport">Give milestone 5 feedback</button>`);
 function preview(){const f=Number($('#transitFunding').value);$('#transitFundingValue').textContent=f+'%';$('#transitPreview').textContent=`Transit upkeep at this setting: ${fmt((s.busStops*5+(s.railTiles+s.railTunnelTiles)*.2+s.subwayTiles*.4+c.tiles.reduce((v,t)=>v+(STATIONS[t.type]?.upkeep||0),0))*f/100)}/month. Current fares: ${fmt(s.transitFare)}/month. Fares change with actual usage.`;}
 document.querySelectorAll('[data-transit-tool]').forEach(b=>b.onclick=()=>{setTool(b.dataset.transitTool);close();});$('#railMap').onclick=()=>{setLayer('rail');close();};$('#subwayMap').onclick=()=>{setLayer('subway');close();};$('#transitFunding').oninput=preview;$('#applyTransit').onclick=()=>{const r=changeTransit(c,Number($('#transitFunding').value));if(!r.ok)return notify(r.error);recompute(c);clearUndo();update();save();notify('Transit budget applied.');showTransport(ui);};$('#trafficMap').onclick=()=>{setLayer('traffic');close();};$('#transitMap').onclick=()=>{setLayer('transit');close();};$('#buildBus').onclick=()=>{setTool('busStop');close();};$('#buildRoad').onclick=()=>{setTool('road');close();};$('#reviewTransport').onclick=()=>review(5);preview();
 if(document.querySelector('#showTunnels'))document.querySelector('#showTunnels').onclick=()=>{setLayer('tunnels');close();};
}
